    /// A tap on a call bubble: the same sheet a link gets, with the contact's name over one row
    /// that places the same kind of call again. The row goes through audioVideoCall, so every
    /// check that guards a call from the bar - a call already in progress, feature access, the
    /// microphone or camera permission, the network - guards this one too.
    @objc private func callBubbleTapped(_ sender: UITapGestureRecognizer) {
        guard !listMotion.isMoving(tableChatView) else { return }
        let video = sender.name == "video"
        let again = UIBarButtonItem()
        again.tag = video ? 1 : 0
        let row = LinkActionSheetViewController.Action(
            title: (video ? "Video call" : "Call").localized(),
            systemImageName: video ? "video" : "phone",
            handler: { [weak self] in self?.audioVideoCall(sender: again) })
        let sheet = LinkActionSheetViewController(title: titleText ?? "", actions: [row])
        sheet.presentAsBottomSheet(from: self)
    }

    @objc func audioVideoCall(sender: UIBarButtonItem) {
        if sender.tag == 0 {
            if APIS.blockedByCallInProgress() {
                return
            }
            if !Nexilis.checkingAccess(key: "audio_call") {
                self.view.makeToast("Feature disabled..".localized(), duration: 3)
                return
            }
            // Fix: the permission was asked for and waited on, and the alert on refusal said
            // "please allow it in your settings" whether or not there was anything to allow.
            // Asked through the one gate now - see APIS.withCapture - which runs this on the far
            // side of the answer, so allowing the microphone and getting the call are one tap;
            // offers Settings when it has been refused for good; and says so when our own call
            // already has the microphone.
            APIS.withCapture(.microphone) { [self] in
                guard let pin = dataPerson["f_pin"] else {
                    return
                }
                if !CheckConnection.isConnectedToNetwork() {
                    let imageView = UIImageView(image: UIImage(systemName: "xmark.circle.fill"))
                    imageView.tintColor = .white
                    let banner = FloatingNotificationBanner(title: "Check your connection".localized(), subtitle: nil, titleFont: UIFont.systemFont(ofSize: 16), titleColor: nil, titleTextAlign: .left, subtitleFont: nil, subtitleColor: nil, subtitleTextAlign: nil, leftView: imageView, rightView: nil, style: .danger, colors: nil, iconPosition: .center)
                    banner.show()
                    return
                }
                let controller = QmeraAudioViewController()
                controller.user = User.getData(pin: pin)
                controller.isOutgoing = true
                controller.modalPresentationStyle = .overCurrentContext
                present(controller, animated: true, completion: nil)
            }
        } else {
            if APIS.blockedByCallInProgress() {
                return
            }
            if !Nexilis.checkingAccess(key: "video_call") {
                self.view.makeToast("Feature disabled..".localized(), duration: 3)
                return
            }
            // Fix: the alert here fired only when the CAMERA was refused. A video call with the
            // camera allowed and the microphone refused went ahead - a call nobody could be heard
            // on. Both are asked for together now, and either one refused stops it.
            // Asked through the one gate now - see APIS.withCapture - which runs this on the far
            // side of the answer, so allowing the microphone and getting the call are one tap;
            // offers Settings when it has been refused for good; and says so when our own call
            // already has the microphone.
            APIS.withCapture(.cameraAndMicrophone) { [self] in
                if !CheckConnection.isConnectedToNetwork() {
                    let imageView = UIImageView(image: UIImage(systemName: "xmark.circle.fill"))
                    imageView.tintColor = .white
                    let banner = FloatingNotificationBanner(title: "Check your connection".localized(), subtitle: nil, titleFont: UIFont.systemFont(ofSize: 16), titleColor: nil, titleTextAlign: .left, subtitleFont: nil, subtitleColor: nil, subtitleTextAlign: nil, leftView: imageView, rightView: nil, style: .danger, colors: nil, iconPosition: .center)
                    banner.show()
                    return
                }
                let videoVC = AppStoryBoard.Palio.instance.instantiateViewController(withIdentifier: "videoVCQmera") as! QmeraVideoViewController
                videoVC.dataPerson.append(dataPerson)
                show(videoVC, sender: nil)
            }
        }
    }
    
